-- Datos de PRUEBA del clima laboral en la empresa «Demo» de producción (5 de octubre de 2026)
--
-- Pedido del dueño: ver cómo se ve el clima laboral con todo septiembre lleno. SOLO para la empresa
-- Demo (cmrfu0b5m0008avi678kzeldr), que es la suya de pruebas: nada de esto toca a un cliente.
--
-- Qué agrega:
--   - 12 personas de prueba (id 'democlima-col-01' a '12', cédula 'DEMO-01' a '12'), repartidas en
--     «Sede principal» y «Sede Robledo». Salen en todo Demo mientras existan: Colaboradores, reportes y
--     la nómina, con un salario de ejemplo de $ 1.500.000.
--   - 306 caritas de septiembre (id 'democlima-…'): las de esas 12 y las de las dos personas activas de
--     siempre. Valentina Ríos y Julián Torres terminan el mes con 8 respuestas negativas seguidas, así que
--     salen en «Necesitan atención» (y al abrir el panel se les abre su caso de seguimiento).
--   - 8 observaciones con nombre y 10 notas del buzón confidencial. El autor de las notas es FALSO
--     ('demo:sin-autor'): el comando de revelar no las puede descifrar, y está bien, son de mentira.
--
-- Lo que NO trae: marcaciones. Por eso «Respondieron» dice que nadie cerró jornada en el kiosco: la
-- participación se calcula contra las jornadas, y se dejó así para no llenar de horas falsas la nómina.
--
-- Probado antes en local, LETRA POR LETRA el mismo, contra una réplica con la forma de Demo:
--   npx ts-node prisma/probar-demo-clima-sql.ts <este SQL> <el conteo> <el borrado>
-- Corrido en producción el 5 de octubre de 2026 desde phpMyAdmin, con la huella SHA-256 del texto
-- comparada contra la del probado (da65c598…). Insertó 12, 12, 306, 8 y 10 filas.

-- ============================================================================
-- AGREGAR (ya corrido: no volver a correr, chocaría con las llaves)
-- ============================================================================
INSERT INTO colaboradores (id, empresaId, nombre, apellido, cedula, cargo, salarioMensual, modalidad, activo, creadoEn, actualizadoEn) VALUES ('democlima-col-01', 'cmrfu0b5m0008avi678kzeldr', 'Laura', 'Martínez', 'DEMO-01', 'Cajera', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-02', 'cmrfu0b5m0008avi678kzeldr', 'Andrés', 'Gómez', 'DEMO-02', 'Mesero', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-03', 'cmrfu0b5m0008avi678kzeldr', 'Valentina', 'Ríos', 'DEMO-03', 'Cocinera', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-04', 'cmrfu0b5m0008avi678kzeldr', 'Camilo', 'Herrera', 'DEMO-04', 'Auxiliar de bodega', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-05', 'cmrfu0b5m0008avi678kzeldr', 'Daniela', 'Castro', 'DEMO-05', 'Mesera', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-06', 'cmrfu0b5m0008avi678kzeldr', 'Santiago', 'López', 'DEMO-06', 'Cocinero', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-07', 'cmrfu0b5m0008avi678kzeldr', 'Mariana', 'Vargas', 'DEMO-07', 'Cajera', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-08', 'cmrfu0b5m0008avi678kzeldr', 'Julián', 'Torres', 'DEMO-08', 'Domiciliario', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-09', 'cmrfu0b5m0008avi678kzeldr', 'Sofía', 'Ramírez', 'DEMO-09', 'Administradora', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-10', 'cmrfu0b5m0008avi678kzeldr', 'Felipe', 'Moreno', 'DEMO-10', 'Mesero', 1500000, 'PRESENCIAL', 1, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000'), ('democlima-col-11', 'cmrfu0b5m0008avi678kzeldr', 'Natalia', 'Ortiz', 'DEMO-11', 'Cocinera', 1500000, '