INSERT INTO colaboradores_sedes (colaboradorId, sedeId, creadoEn) SELECT m.colaboradorId, s.id, '2026-08-25 13:00:00.000' FROM (SELECT 'democlima-col-01' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-02' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-03' AS colaboradorId, 'Sede Robledo' AS sede UNION ALL SELECT 'democlima-col-04' AS colaboradorId, 'Sede Robledo' AS sede UNION ALL SELECT 'democlima-col-05' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-06' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-07' AS colaboradorId, 'Sede Robledo' AS sede UNION ALL SELECT 'democlima-col-08' AS colaboradorId, 'Sede Robledo' AS sede UNION ALL SELECT 'democlima-col-09' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-10' AS colaboradorId, 'Sede Robledo' AS sede UNION ALL SELECT 'democlima-col-11' AS colaboradorId, 'Sede principal' AS sede UNION ALL SELECT 'democlima-col-12' AS colaboradorId, 'Sede Robledo' AS sede) m JOIN sedes s ON s.empresaId = 'cmrfu0b5m0008avi678kzeldr' AND s.activa = 1 AND s.nombre = m.sede;
INSERT INTO calificaciones_clima (id, empresaId, colaboradorId, fecha, carita, motivos, observacion, creadoEn, actualizadoEn) SELECT CONCAT('democlima-', p.ref, '-', LPAD(d.n, 2, '0')), 'cmrfu0b5m0008avi678kzeldr', p.colId, TIMESTAMP('2026-09-01 05:00:00.000') + INTERVAL (d.n - 1) DAY, CAST(SUBSTRING(p.patron, d.n, 1) AS UNSIGNED), CASE WHEN SUBSTRING(p.patron, d.n, 1) IN ('1', '2', '3') THEN CASE WHEN CRC32(CONCAT(p.ref, d.n)) % 3 = 0 THEN JSON_ARRAY(p.m1, p.m2) ELSE JSON_ARRAY(p.m1) END ELSE JSON_ARRAY() END, NULL, TIMESTAMP('2026-09-01 22:00:00.000') + INTERVAL (d.n - 1) DAY + INTERVAL (CRC32(CONCAT(p.ref, '-', d.n)) % 100) MINUTE, TIMESTAMP('2026-09-01 22:00:00.000') + INTERVAL (d.n - 1) DAY + INTERVAL (CRC32(CONCAT(p.ref, '-', d.n)) % 100) MINUTE FROM (SELECT '01' AS ref, 'democlima-col-01' AS colId, '54553-4555-3--54445-455454-445' AS patron, 'Mucho trabajo' AS m1, 'Algo personal' AS m2 UNION ALL SELECT '02' AS ref, 'democlima-col-02' AS colId, '22-41-243--3-2225-3-24-212--35' AS patron, 'Mucho trabajo' AS m1, 'Jefe o supervisor' AS m2 UNION ALL SELECT '03' AS ref, 'democlima-col-03' AS colId, '434-4-4-4445-43-453-522212-212' AS patron, 'Mucho trabajo' AS m1, 'Me tocó quedarme más tiempo' AS m2 UNION ALL SELECT '04' AS ref, 'democlima-col-04' AS colId, '33334-444344--34-33-33433--343' AS patron, 'Me tocó quedarme más tiempo' AS m1, 'Compañeros' AS m2 UNION ALL SELECT '05' AS ref, 'democlima-col-05' AS colId, '55554-44-2-4-54445--444555-545' AS patron, 'Compañeros' AS m1, 'Algo personal' AS m2 UNION ALL SELECT '06' AS ref, 'democlima-col-06' AS colId, '3-533-344442-221133-344355-444' AS patron, 'Jefe o supervisor' AS m1, 'Mucho trabajo' AS m2 UNION ALL SELECT '07' AS ref, 'democlima-col-07' AS colId, '53553--445---55-444-55-53--44-' AS patron, 'Algo personal' AS m1, 'Mucho trabajo' AS m2 UNION ALL SELECT '08' AS ref, 'democlima-col-08' AS colId, '44333-4-4544-334445-422121-111' AS patron, 'Me tocó quedarme más tiempo' AS m1, 'Jefe o supervisor' AS m2 UNION ALL SELECT '09' AS ref, 'democlima-col-09' AS colId, '554-5-553555-55-535-554554-5-5' AS patron, 'Mucho trabajo' AS m1, 'Algo personal' AS m2 UNION ALL SELECT '10' AS ref, 'democlima-col-10' AS colId, '45-33-4-432--344--4----43-----' AS patron, 'Compañeros' AS m1, 'Mucho trabajo' AS m2 UNION ALL SELECT '11' AS ref, 'democlima-col-11' AS colId, '4331--35-241-241313-4-13---352' AS patron, 'Compañeros' AS m1, 'Jefe o supervisor' AS m2 UNION ALL SELECT '12' AS ref, 'democlima-col-12' AS colId, '43543-4-54-4-4--5-4-4554-4-4-3' AS patron, 'Mucho trabajo' AS m1, 'Me tocó quedarme más tiempo' AS m2 UNION ALL SELECT 'r1' AS ref, (SELECT x.id FROM (SELECT id FROM colaboradores WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND activo = 1 AND id NOT LIKE 'democlima-%' ORDER BY creadoEn, id LIMIT 1 OFFSET 0) x) AS colId, '34434-434444-444445-54255--545' AS patron, 'Mucho trabajo' AS m1, 'Algo personal' AS m2 UNION ALL SELECT 'r2' AS ref, (SELECT x.id FROM (SELECT id FROM colaboradores WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND activo = 1 AND id NOT LIKE 'democlima-%' ORDER BY creadoEn, id LIMIT 1 OFFSET 1) x) AS colId, '53-34--254-3-3333-3-334344-534' AS patron, 'Compañeros' AS m1, 'Mucho trabajo' AS m2) p CROSS JOIN (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n UNION ALL SELECT 7 AS n UNION ALL SELECT 8 AS n UNION ALL SELECT 9 AS n UNION ALL SELECT 10 AS n UNION ALL SELECT 11 AS n UNION ALL SELECT 12 AS n UNION ALL SELECT 13 AS n UNION ALL SELECT 14 AS n UNION ALL SELECT 15 AS n UNION ALL SELECT 16 AS n UNION ALL SELECT 17 AS n UNION ALL SELECT 18 AS n UNION ALL SELECT 19 AS n UNION ALL SELECT 20 AS n UNION ALL SELECT 21 AS n UNION ALL SELECT 22 AS n UNION ALL SELECT 23 AS n UNION ALL SELECT 24 AS n UNION ALL SELECT 25 AS n UNION ALL SELECT 26 AS n UNION ALL SELECT 27 AS n UNION ALL SELECT 28 AS n UNION ALL SELECT 29 AS n UNION ALL SELECT 30 AS n) d WHERE SUBSTRING(p.patron, d.n, 1) <> '-' AND p.colId IS NOT NULL;
UPDATE calificaciones_clima SET observacion = CASE id WHEN 'democlima-01-18' THEN 'Todo bien, la caja cuadró perfecto.' WHEN 'democlima-02-15' THEN 'Mucha gente el fin de semana y éramos pocos.' WHEN 'democlima-03-30' THEN 'Esta semana nos tocó cubrir dos turnos más y no alcanzamos a descansar.' WHEN 'democlima-05-17' THEN 'Me gustó el cambio de horario.' WHEN 'democlima-06-01' THEN 'Hubo un problema con el jefe de cocina, ya lo hablamos.' WHEN 'democlima-08-30' THEN 'Los domicilios de la noche se están quedando sin quién los haga y me toca salir tarde.' WHEN 'democlima-09-15' THEN 'Muy buen ambiente esta semana, gracias por el apoyo.' WHEN 'democlima-11-16' THEN 'Falta coordinación en el cambio de turno.' ELSE observacion END WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND id IN ('democlima-01-18', 'democlima-02-15', 'democlima-03-30', 'democlima-05-17', 'democlima-06-01', 'democlima-08-30', 'democlima-09-15', 'democlima-11-16');
INSERT INTO observaciones_confidenciales (id, empresaId, semana, visibleDesde, texto, autorCifrado) VALUES ('democlima-nota-01', 'cmrfu0b5m0008avi678kzeldr', '2026-08-31 05:00:00.000', '2026-09-03 05:00:00.000', 'Siento que en la noche siempre somos los mismos los que cerramos.', 'demo:sin-autor'), ('democlima-nota-02', 'cmrfu0b5m0008avi678kzeldr', '2026-08-31 05:00:00.000', '2026-09-05 05:00:00.000', 'Me gustaría que avisaran los cambios de turno con más tiempo.', 'demo:sin-autor'), ('democlima-nota-03', 'cmrfu0b5m0008avi678kzeldr', '2026-09-07 05:00:00.000', '2026-09-10 05:00:00.000', 'Hay un compañero que trata mal a los nuevos.', 'demo:sin-autor'), ('democlima-nota-04', 'cmrfu0b5m0008avi678kzeldr', '2026-09-07 05:00:00.000', '2026-09-12 05:00:00.000', 'Gracias por el almuerzo del viernes, se sintió bonito.', 'demo:sin-autor'), ('democlima-nota-05', 'cmrfu0b5m0008avi678kzeldr', '2026-09-14 05:00:00.000', '2026-09-16 05:00:00.000', 'El supervisor nos grita delante de los clientes.', 'demo:sin-autor'), ('democlima-nota-06', 'cmrfu0b5m0008avi678kzeldr', '2026-09-14 05:00:00.000', '2026-09-18 05:00:00.000', 'No tenemos dónde guardar las cosas, se pierden.', 'demo:sin-autor'), ('democlima-nota-07', 'cmrfu0b5m0008avi678kzeldr', '2026-09-14 05:00:00.000', '2026-09-20 05:00:00.000', 'La nevera de la cocina lleva una semana fallando.', 'demo:sin-autor'), ('democlima-nota-08', 'cmrfu0b5m0008avi678kzeldr', '2026-09-21 05:00:00.000', '2026-09-24 05:00:00.000', 'Estoy muy cansado, llevo muchas semanas sin un domingo libre.', 'demo:sin-autor'), ('democlima-nota-09', 'cmrfu0b5m0008avi678kzeldr', '2026-09-21 05:00:00.000', '2026-09-26 05:00:00.000', 'Me gustaría aprender a manejar la caja.', 'demo:sin-autor'), ('democlima-nota-10', 'cmrfu0b5m0008avi678kzeldr', '2026-09-28 05:00:00.000', '2026-09-30 05:00:00.000', 'Las propinas no se están repartiendo igual para todos.', 'demo:sin-autor');

-- ============================================================================
-- CONTAR (solo lectura): 12, 12, 306, 8 y 10 mientras estén; todo en 0 después de borrar
-- ============================================================================
SELECT (SELECT COUNT(*) FROM colaboradores WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND id LIKE 'democlima-col-%') AS personas, (SELECT COUNT(*) FROM colaboradores_sedes WHERE colaboradorId LIKE 'democlima-col-%') AS sedes, (SELECT COUNT(*) FROM calificaciones_clima WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND id LIKE 'democlima-%') AS caritas, (SELECT COUNT(*) FROM calificaciones_clima WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND id LIKE 'democlima-%' AND observacion IS NOT NULL) AS con_observacion, (SELECT COUNT(*) FROM observaciones_confidenciales WHERE empresaId = 'cmrfu0b5m0008avi678kzeldr' AND id LIKE 'democlima-%') AS notas;

